mapper.select:
SELECT u.id, u.username, u.password, u.real_name, u.phone, u.resident_id, r.name AS resident_name, u.status, u.is_deleted, u.created_at, u.updated_at FROM sys_user u LEFT JOIN resident r ON r.id = u.resident_id AND r.is_deleted = 0 WHERE u.is_deleted = 0
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND u.status = #{status}
ORDER BY u.id DESC LIMIT #{pageSize} OFFSET #{offset}

